//! `librosa.yin`, `librosa.pyin`, `librosa.salience`, `librosa.interp_harmonics`
//! and `librosa.f0_harmonics` references (fixture `pitch.json`, generated by
//! `cases/pitch.py`).
//!
//! YIN/pYIN run on the shared signals. The cumulative mean normalised
//! difference is computed exactly as librosa does (FFT autocorrelation of the
//! same padded length, same cumsum order); the only round-off source is the FFT
//! itself (rustfft vs pocketfft, ~1e-16 of the frame energy), which moves CMND
//! values by ~1e-13 and therefore the refined period by far less than 1e-9.
//! Decisions (trough choice, pitch bin, voiced flag, Viterbi path) must match
//! exactly. The harmonic helpers get the stored spectrogram as input and use
//! SciPy's / NumPy's interpolation formulas, so they agree to round-off.

use audio_samples::operations::pitch_tracking::{
    AudioPitchTracking, FrequencyGrid, PyinConfig, SalienceAggregate, SalienceConfig, UnvoicedFill,
    YinConfig, f0_harmonics, interp_harmonics, salience,
};
use audio_samples::{AudioSamples, StftPadMode};
use ndarray::{Array2, Array3, Axis};
use serde_json::Value;
use std::num::NonZeroUsize;

use crate::common::{arr2, arr3, assert_close, errors, load, mono, stereo};

/// f0 from the same CMND up to FFT round-off (see module docs). Measured
/// <= 3.3e-16 relative (yin) and bit-identical (pyin, bin centres); 1e-11
/// leaves room for other FFT / libm implementations.
const RTOL_F0: f64 = 1e-11;
/// Voicing probabilities are sums of Beta-prior masses; ours come from an
/// exact binomial / continued-fraction incomplete beta, SciPy's from Boost
/// (both within ~1e-14), and the dot product order differs from BLAS.
/// Measured <= 2.6e-15 absolute (non-integer Beta parameters).
const RTOL_PROB: f64 = 1e-11;
/// Interpolation and aggregation of identical inputs with identical formulas:
/// only summation-order / ulp differences remain.
const RTOL_INTERP: f64 = 1e-12;

fn fixture() -> &'static Value {
    use std::sync::OnceLock;
    static F: OnceLock<Value> = OnceLock::new();
    F.get_or_init(|| load("pitch"))
}

fn nz(v: &Value) -> Option<NonZeroUsize> {
    v.as_u64().and_then(|x| NonZeroUsize::new(x as usize))
}

fn pad_mode(v: &Value) -> StftPadMode {
    match v.as_str().expect("pad_mode") {
        "constant" => StftPadMode::Constant,
        "reflect" => StftPadMode::Reflect,
        "edge" => StftPadMode::Edge,
        "symmetric" => StftPadMode::Symmetric,
        other => panic!("unknown pad_mode {other}"),
    }
}

fn input(name: &str) -> AudioSamples<'static, f64> {
    if name == "stereo" {
        stereo()
    } else {
        mono(name)
    }
}

/// A `(channels, n)` array from a 1-D (mono) or 2-D fixture array.
fn rows_f64(v: &Value) -> Array2<f64> {
    if v[0].is_array() {
        arr2(v)
    } else {
        arr2(&Value::Array(vec![v.clone()]))
    }
}

fn rows_bool(v: &Value) -> Array2<bool> {
    let rows: Vec<Vec<bool>> = if v[0].is_array() {
        v.as_array()
            .unwrap()
            .iter()
            .map(|r| {
                r.as_array()
                    .unwrap()
                    .iter()
                    .map(|b| b.as_bool().unwrap())
                    .collect()
            })
            .collect()
    } else {
        vec![
            v.as_array()
                .unwrap()
                .iter()
                .map(|b| b.as_bool().unwrap())
                .collect(),
        ]
    };
    let (r, c) = (rows.len(), rows[0].len());
    Array2::from_shape_vec((r, c), rows.into_iter().flatten().collect()).unwrap()
}

/// Nested array where `null` encodes NaN.
fn nullable(v: &Value) -> Vec<f64> {
    match v {
        Value::Array(a) => a.iter().flat_map(nullable).collect(),
        Value::Null => vec![f64::NAN],
        x => vec![x.as_f64().expect("number")],
    }
}

#[track_caller]
fn assert_close_nan(what: &str, actual: &[f64], expected: &[f64], rtol: f64) {
    assert_eq!(actual.len(), expected.len(), "{what}: length");
    for (i, (a, e)) in actual.iter().zip(expected).enumerate() {
        assert_eq!(
            a.is_nan(),
            e.is_nan(),
            "{what}: NaN mismatch at {i} ({a} vs {e})"
        );
    }
    let a: Vec<f64> = actual.iter().copied().filter(|v| !v.is_nan()).collect();
    let e: Vec<f64> = expected.iter().copied().filter(|v| !v.is_nan()).collect();
    let (abs, _) = errors(a.iter(), e.iter());
    eprintln!("{what}: max abs {abs:.3e}");
    assert_close(what, &a, &e, rtol, 0.0);
}

fn yin_config(c: &Value) -> YinConfig {
    YinConfig {
        fmin: c["fmin"].as_f64().unwrap(),
        fmax: c["fmax"].as_f64().unwrap(),
        frame_length: nz(&c["frame_length"]).unwrap(),
        hop_length: nz(&c["hop_length"]),
        trough_threshold: c["trough_threshold"].as_f64().unwrap(),
        center: c["center"].as_bool().unwrap(),
        pad_mode: pad_mode(&c["pad_mode"]),
    }
}

fn pyin_config(c: &Value) -> PyinConfig {
    let beta = c["beta_parameters"].as_array().unwrap();
    PyinConfig {
        fmin: c["fmin"].as_f64().unwrap(),
        fmax: c["fmax"].as_f64().unwrap(),
        frame_length: nz(&c["frame_length"]).unwrap(),
        hop_length: nz(&c["hop_length"]),
        n_thresholds: nz(&c["n_thresholds"]).unwrap(),
        beta_parameters: (beta[0].as_f64().unwrap(), beta[1].as_f64().unwrap()),
        boltzmann_parameter: c["boltzmann_parameter"].as_f64().unwrap(),
        resolution: c["resolution"].as_f64().unwrap(),
        max_transition_rate: c["max_transition_rate"].as_f64().unwrap(),
        switch_prob: c["switch_prob"].as_f64().unwrap(),
        no_trough_prob: c["no_trough_prob"].as_f64().unwrap(),
        // The fixture uses fill_na=None so every f0 is finite.
        fill: UnvoicedFill::BestGuess,
        center: c["center"].as_bool().unwrap(),
        pad_mode: pad_mode(&c["pad_mode"]),
        transition_min_prob: c["transition_min_prob"].as_f64(),
    }
}

#[test]
fn yin_matches_librosa() {
    for (name, case) in fixture()["yin"].as_object().unwrap() {
        let cfg = yin_config(&case["config"]);
        let audio = input(case["signal"].as_str().unwrap());
        let got = audio.yin(&cfg).unwrap();
        let want = rows_f64(&case["f0"]);
        assert_eq!(got.dim(), want.dim(), "yin {name}: shape");
        let (abs, rel) = errors(got.iter(), want.iter());
        eprintln!("yin {name}: max abs {abs:.3e}, rel {rel:.3e}");
        assert_close(
            &format!("yin {name}"),
            got.iter(),
            want.iter(),
            RTOL_F0,
            0.0,
        );
    }
}

#[test]
fn yin_default_config_is_librosa_default() {
    // librosa requires fmin/fmax; everything else equals YinConfig::default().
    let c = &fixture()["yin"]["notes_default"]["config"];
    let cfg = yin_config(c);
    let d = YinConfig::default().with_fmin(cfg.fmin).with_fmax(cfg.fmax);
    assert_eq!(cfg, d);
}

#[test]
fn pyin_matches_librosa() {
    for (name, case) in fixture()["pyin"].as_object().unwrap() {
        let cfg = pyin_config(&case["config"]);
        let audio = input(case["signal"].as_str().unwrap());
        let got = audio.pyin(&cfg).unwrap();
        let want_flag = rows_bool(&case["voiced_flag"]);
        assert_eq!(got.voiced_flag, want_flag, "pyin {name}: voiced_flag");
        let want_f0 = rows_f64(&case["f0"]);
        let (abs, rel) = errors(got.f0.iter(), want_f0.iter());
        let want_p = rows_f64(&case["voiced_prob"]);
        let (pabs, _) = errors(got.voiced_prob.iter(), want_p.iter());
        eprintln!(
            "pyin {name}: f0 max abs {abs:.3e} rel {rel:.3e}; voiced_prob max abs {pabs:.3e}"
        );
        assert_close(
            &format!("pyin {name} f0"),
            got.f0.iter(),
            want_f0.iter(),
            RTOL_F0,
            0.0,
        );
        assert_close(
            &format!("pyin {name} voiced_prob"),
            got.voiced_prob.iter(),
            want_p.iter(),
            RTOL_PROB,
            1e-15,
        );

        // The default NaN fill: voiced frames unchanged, unvoiced frames NaN.
        let nan = audio
            .pyin(&cfg.clone().with_fill(UnvoicedFill::Nan))
            .unwrap();
        for ((&v, &flag), &g) in nan.f0.iter().zip(&want_flag).zip(&got.f0) {
            if flag {
                assert_eq!(v, g);
            } else {
                assert!(v.is_nan());
            }
        }
    }
}

#[test]
fn pyin_default_config_is_librosa_default() {
    let c = &fixture()["pyin"]["notes_default"]["config"];
    let cfg = pyin_config(c);
    let d = PyinConfig::default()
        .with_fmin(cfg.fmin)
        .with_fmax(cfg.fmax)
        .with_fill(UnvoicedFill::BestGuess);
    assert_eq!(cfg, d);
}

struct Harm {
    s: Array3<f64>,
    freqs: ndarray::Array1<f64>,
    freqs_tv: Array3<f64>,
    f0: Array2<f64>,
}

fn harm() -> Harm {
    let h = &fixture()["harmonics"];
    let s = arr2(&h["S"]).insert_axis(Axis(0));
    let freqs = ndarray::Array1::from(nullable(&h["freqs"]));
    let freqs_tv = arr2(&h["freqs_tv"]).insert_axis(Axis(0));
    let f0 = Array2::from_shape_vec((1, s.dim().2), nullable(&h["f0"])).unwrap();
    Harm {
        s,
        freqs,
        freqs_tv,
        f0,
    }
}

fn f64_list(v: &Value) -> Vec<f64> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_f64().unwrap())
        .collect()
}

#[test]
fn interp_harmonics_matches_librosa() {
    let d = harm();
    let c = &fixture()["harmonics"]["interp_harmonics"];
    let hs = f64_list(&c["harmonics"]);
    let fixed = FrequencyGrid::Fixed(d.freqs.view());
    let tv = FrequencyGrid::TimeVarying(d.freqs_tv.view());
    for (key, grid, fill) in [
        ("fixed", fixed, 0.0),
        ("fixed_fill", fixed, -1.0),
        ("time_varying", tv, 0.0),
    ] {
        let got = interp_harmonics(d.s.view(), grid, &hs, fill).unwrap();
        let want = arr3(&c[key]);
        assert_eq!(got.index_axis(Axis(0), 0).dim(), want.dim(), "{key}");
        let (abs, _) = errors(got.iter(), want.iter());
        eprintln!("interp_harmonics {key}: max abs {abs:.3e}");
        assert_close(
            &format!("interp_harmonics {key}"),
            got.iter(),
            want.iter(),
            RTOL_INTERP,
            0.0,
        );
    }
}

#[test]
fn salience_matches_librosa() {
    let d = harm();
    let c = &fixture()["harmonics"]["salience"];
    let hs = f64_list(&c["harmonics"]);
    let w = f64_list(&c["weights"]);
    let fixed = FrequencyGrid::Fixed(d.freqs.view());
    let tv = FrequencyGrid::TimeVarying(d.freqs_tv.view());
    let nofilter = |a| {
        SalienceConfig::new()
            .with_aggregate(a)
            .with_filter_peaks(false)
    };
    let cases = [
        ("default", fixed, SalienceConfig::default()),
        (
            "weighted",
            fixed,
            SalienceConfig::new().with_weights(Some(w.clone())),
        ),
        (
            "weighted_fill0",
            fixed,
            SalienceConfig::new()
                .with_weights(Some(w.clone()))
                .with_fill_value(0.0),
        ),
        ("max_nofilter", fixed, nofilter(SalienceAggregate::Max)),
        ("sum_nofilter", fixed, nofilter(SalienceAggregate::Sum)),
        (
            "median_nofilter",
            fixed,
            nofilter(SalienceAggregate::Median),
        ),
        ("min_nofilter", fixed, nofilter(SalienceAggregate::Min)),
        (
            "time_varying",
            tv,
            SalienceConfig::new().with_weights(Some(w)),
        ),
    ];
    for (key, grid, cfg) in cases {
        let got = salience(d.s.view(), grid, &hs, &cfg).unwrap();
        let want = nullable(&c[key]);
        let got: Vec<f64> = got.iter().copied().collect();
        assert_close_nan(&format!("salience {key}"), &got, &want, RTOL_INTERP);
    }
}

#[test]
fn f0_harmonics_matches_librosa() {
    let d = harm();
    let c = &fixture()["harmonics"]["f0_harmonics"];
    let hs = f64_list(&c["harmonics"]);
    let fixed = FrequencyGrid::Fixed(d.freqs.view());
    let tv = FrequencyGrid::TimeVarying(d.freqs_tv.view());
    for (key, grid, fill) in [
        ("fixed", fixed, 0.0),
        ("fixed_fill", fixed, -2.0),
        ("time_varying", tv, 0.0),
    ] {
        let got = f0_harmonics(d.s.view(), d.f0.view(), grid, &hs, fill).unwrap();
        let want = arr2(&c[key]);
        assert_eq!(got.index_axis(Axis(0), 0).dim(), want.dim(), "{key}");
        let (abs, _) = errors(got.iter(), want.iter());
        eprintln!("f0_harmonics {key}: max abs {abs:.3e}");
        assert_close(
            &format!("f0_harmonics {key}"),
            got.iter(),
            want.iter(),
            RTOL_INTERP,
            0.0,
        );
    }
}
